import{_ as r,l as n,o as e,c as s,v as o,p as i,x as t,d,i as E,S as p}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"SambaNova 数据流","description":"","frontmatter":{"title":"SambaNova 数据流","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/sambanova-dataflow.md","filePath":"llm/sambanova-dataflow.md","lastUpdated":1789023840000}'),m={name:"llm/sambanova-dataflow.md"};function c(A,a,h,B,_,b){const l=n("Mermaid");return e(),s("div",null,[a[1]||(a[1]=o('<h1 id="sambanova-数据流" tabindex="-1">SambaNova 数据流 <a class="header-anchor" href="#sambanova-数据流" aria-label="Permalink to &quot;SambaNova 数据流&quot;">​</a></h1><div class="epigraph"><p>把层融进一片可重配置的数据通路，让张量在芯片上流动，而不是每个算子 launch 一次核、再回 HBM。图能静态融合时，带宽墙后退；图在运行时打结时，通路空转。</p><footer>—— SambaNova RDU / 数据流体系的公开描述</footer></div><p><a href="/llm/groq-lpu-deterministic">Groq</a> 把确定性推到时钟级。本课 SambaNova 的 RDU 走 <strong>可重配置数据流</strong>：空间上铺算子图，时间上流水，目标覆盖训练与推理更完整的图，而不只是 decode SLA。缺口是数据流机与 GPU kernel 启动模型差在哪——以及为何 LLM 的动态形状仍让空间架构难受。对比时与 TPU 的 XLA 融合、GPU 的 CUDA Graph 是亲戚，不是同一硬件。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>GPU 上每个 PyTorch 算子可能对应一次 kernel，中间张量写 HBM，算术强度被切碎。编译器融合（XLA、torch.compile）能补一部分，但仍受 SIMT 与缓存层次约束。数据流芯片把算子映射到固定或可配置的功能单元网络，张量沿边流，中间值留在片上。墙变成：图有多大、能否塞进一片（或一组）RDU，以及重配置的间隔。</p><p>LLM 训练有反向、有动态损失缩放、有变长、有 MoE 路由。数据流图要么做大而保守的静态形状，要么频繁重配置。问题是 <strong>融合收益 vs 重配置 / padding 成本</strong>。</p><p><span class="marginnote">公开叙事强调软件把模型编译到 RDU 图。没有大规模公开的 NCCL 对标表格。本课讲机制，不编造某代对标 H100 的加速比。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>编译器把计算图划分到一颗或多颗 RDU，插入片上缓冲与芯片间链路。能融合的 MLP 与注意力块尽量整块驻留。主机负责数据与检查点，类似其他加速器。集群仍需要某种集体：要么在数据流图里显式加 All-Reduce 节点，要么在主机 / 专用互连上做——不要默认有一份 NCCL。</p>',9)),(e(),i(p,null,{default:t(()=>[E(l,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20LR%0A%20%20GRAPH%5B%22%E8%AE%AD%E7%BB%83%20%2F%20%E6%8E%A8%E7%90%86%E5%9B%BE%22%5D%20--%3E%20MAP%5B%22%E6%98%A0%E5%B0%84%E5%88%B0%20RDU%20%E6%95%B0%E6%8D%AE%E9%80%9A%E8%B7%AF%22%5D%0A%20%20MAP%20--%3E%20FLOW%5B%22%E5%BC%A0%E9%87%8F%E6%B2%BF%E7%89%87%E4%B8%8A%E8%BE%B9%E6%B5%81%E5%8A%A8%22%5D%0A%20%20FLOW%20--%3E%20HBM%5B%22%E5%BF%85%E8%A6%81%E6%97%B6%E8%BF%9B%E5%87%BA%E5%A4%96%E9%83%A8%E5%86%85%E5%AD%98%22%5D%0A%20%20DYN%5B%22%E5%8A%A8%E6%80%81%E8%B7%AF%E7%94%B1%20%2F%20%E5%8F%98%E9%95%BF%22%5D%20--%3E%20RE%5B%22%E9%87%8D%E9%85%8D%E7%BD%AE%E6%88%96%20padding%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>与 GPU 迁移：API 可能包一层框架，但性能来自图是否匹配空间硬件。只跑通不等于吃到数据流。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>空间架构的利用率 = 图在芯片上的驻留时间与流水填充。气泡来自：反压、外部内存访问、集体等待、以及重配置。这与 GPU 的 SM occupancy 不同，不能用同一公式。集体若在图外用主机实现，会把数据流的「中间值不回内存」优势打断——类似 GPU 上融合被 <code>.item()</code> 打断。</p><p><span class="marginnote">和 Cerebras 的空间网格比：一个偏晶圆 mesh 上的核，一个偏可重配置数据通路。都怕全局不规则；都要编译器。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要把数据流写成「永远省 HBM」。图切分后仍会 spill。不要在动态 MoE 上假设与密 MLP 同样的融合。生态与工具链计入对比方法课的软件维。下一课 Tenstorrent 提供另一条：偏 RISC / 多核 + mesh，更接近「可编程核」而不是固定数据通路。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RDU 数据流用空间铺图减少中间 HBM 往返。</li><li>收益取决于静态融合；动态图要 padding 或重配置。</li><li>集群集体必须画进图或接受打断数据流。</li><li>利用率模型不是 SM occupancy，禁止直接套 GPU MFU。</li><li>出处：SambaNova RDU / 数据流公开体系结构描述。</li></ul>',8))])}const D=r(m,[["render",c]]);export{P as __pageData,D as default};
